import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.DXRWYp4X.js";const b=JSON.parse('{"title":"18 · 面试备战与行动清单","description":"","frontmatter":{},"headers":[],"relativePath":"18-面试备战与行动清单.md","filePath":"18-面试备战与行动清单.md","lastUpdated":1789385085000}'),l={name:"18-面试备战与行动清单.md"};function o(i,t,n,s,h,c){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="_18-·-面试备战与行动清单" tabindex="-1">18 · 面试备战与行动清单 <a class="header-anchor" href="#_18-·-面试备战与行动清单" aria-label="Permalink to &quot;18 · 面试备战与行动清单&quot;">​</a></h1><blockquote><p>达标目标：<strong>手写题与八股全覆盖（L2），项目深挖能撑住 30 分钟追问（L3）。</strong> 用法：面试前按本清单刷一轮；<strong>每一题都能&quot;不看资料讲出来&quot;才算过</strong>。所有答案都在对应章节里，标了位置。</p></blockquote><hr><h2 id="一、高频手写题清单-每题闭卷默写-讲边界" tabindex="-1">一、高频手写题清单（每题闭卷默写 + 讲边界） <a class="header-anchor" href="#一、高频手写题清单-每题闭卷默写-讲边界" aria-label="Permalink to &quot;一、高频手写题清单（每题闭卷默写 + 讲边界）&quot;">​</a></h2><h3 id="js-基础-答案见-01-章-§6" tabindex="-1">JS 基础（答案见 01 章 §6） <a class="header-anchor" href="#js-基础-答案见-01-章-§6" aria-label="Permalink to &quot;JS 基础（答案见 01 章 §6）&quot;">​</a></h3><ul><li>[ ] 手写 <code>debounce</code> / <code>throttle</code>（含 leading/trailing 选项）——01 章 §6</li><li>[ ] 手写深拷贝（循环引用 / Symbol / Date / RegExp）——01 章 §1.6</li><li>[ ] 手写 <code>instanceof</code> / <code>new</code> / <code>call</code> / <code>apply</code> / <code>bind</code>——01 章 §4</li><li>[ ] 手写事件总线（on/off/once/emit）——01 章 §6</li><li>[ ] 手写 <code>LRU</code> 缓存（Map 迭代序特性，O(1)）——01 章 §6</li><li>[ ] 手写 <code>Array.map</code> / <code>reduce</code> / <code>flat</code>（含深度控制）</li></ul><h3 id="promise-异步-答案见-01-章-§3" tabindex="-1">Promise / 异步（答案见 01 章 §3） <a class="header-anchor" href="#promise-异步-答案见-01-章-§3" aria-label="Permalink to &quot;Promise / 异步（答案见 01 章 §3）&quot;">​</a></h3><ul><li>[ ] 手写 <code>Promise</code> 核心（状态机 + then 链 + 值穿透 + <strong>resolvePromise</strong>）——01 章 §3.1</li><li>[ ] 手写 <code>Promise.all</code> / <code>allSettled</code> / <code>race</code> / <code>any</code>（差异）——01 章 §3.2</li><li>[ ] 手写并发控制（限流 N 个、全部完成再返回）——01 章 §3.3</li><li>[ ] async/await 的 generator 自动执行器——01 章 §3.4</li></ul><h3 id="框架-工程-答案见-03-04-章" tabindex="-1">框架/工程（答案见 03/04 章） <a class="header-anchor" href="#框架-工程-答案见-03-04-章" aria-label="Permalink to &quot;框架/工程（答案见 03/04 章）&quot;">​</a></h3><ul><li>[ ] 手写 Vue 响应式核心（<code>reactive</code>/<code>effect</code>/track/trigger）——03 章 §1.2</li><li>[ ] 手写 keyed diff（patchChildren）——03 章 §2.2</li><li>[ ] 手写 <code>useState</code> 简版（讲闭包 + 链表，为什么不能条件调用）——03 章 §4.2</li><li>[ ] 写一个 GitLab/GitHub CI yaml（缓存 + paths 过滤）——04 章 §4</li></ul><h2 id="二、八股清单-l2-口试-按-17-章组织-每题-3-分钟" tabindex="-1">二、八股清单（L2 口试，按 17 章组织，每题 3 分钟） <a class="header-anchor" href="#二、八股清单-l2-口试-按-17-章组织-每题-3-分钟" aria-label="Permalink to &quot;二、八股清单（L2 口试，按 17 章组织，每题 3 分钟）&quot;">​</a></h2><h3 id="前端-01-05" tabindex="-1">前端（01-05） <a class="header-anchor" href="#前端-01-05" aria-label="Permalink to &quot;前端（01-05）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题</th><th>出处</th></tr></thead><tbody><tr><td>事件循环一 tick 顺序 + 输出题</td><td>01 章 §2</td></tr><tr><td>闭包/this 四规则/原型链</td><td>01 章 §1/§4</td></tr><tr><td>手写工具类型（DeepReadonly/KebabCase）</td><td>02 章 §5</td></tr><tr><td>判别联合 + 穷尽性检查</td><td>02 章 §1.3</td></tr><tr><td>Vue 响应式 / nextTick / watch vs computed</td><td>03 章 §1</td></tr><tr><td>React Fiber / Hooks 为什么不能条件调用</td><td>03 章 §4</td></tr><tr><td>tree-shaking 为什么必须 ESM</td><td>04 章 §1</td></tr><tr><td>代码分割怎么决策</td><td>04 章 §2</td></tr><tr><td>输入 URL 到首屏全链路</td><td>05 章 §1</td></tr><tr><td>强缓存 vs 协商缓存 + CORS 预检</td><td>05 章 §3</td></tr><tr><td>XSS/CSRF/CSP</td><td>05 章 §4</td></tr><tr><td>LCP/INP/CLS 优化</td><td>05 章 §5</td></tr></tbody></table><h3 id="后端-06-13" tabindex="-1">后端（06-13） <a class="header-anchor" href="#后端-06-13" aria-label="Permalink to &quot;后端（06-13）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题</th><th>出处</th></tr></thead><tbody><tr><td>libuv 六阶段 + setTimeout vs setImmediate</td><td>06 章 §2</td></tr><tr><td>cluster vs worker_threads / 优雅关闭</td><td>06 章 §3/§4</td></tr><tr><td>Fastify 钩子顺序 / 插件 encapsulation</td><td>07 章 §2/§4</td></tr><tr><td>JWT 全流程 + Cookie 四件套 + 双 token</td><td>08 章 §2/§3</td></tr><tr><td>REST 状态码 + 幂等 + 限流</td><td>09 章 §1/§3/§4</td></tr><tr><td>索引/最左前缀/EXPLAIN</td><td>11 章 §1</td></tr><tr><td>隔离级别矩阵 / 乐观锁</td><td>11 章 §2</td></tr><tr><td>缓存三连 + Cache-Aside</td><td>12 章 §1</td></tr><tr><td>CAP / MQ 消费幂等</td><td>12 章 §2</td></tr><tr><td>系统设计五步法</td><td>13 章 §1</td></tr></tbody></table><h3 id="ai-14-17" tabindex="-1">AI（14-17） <a class="header-anchor" href="#ai-14-17" aria-label="Permalink to &quot;AI（14-17）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题</th><th>出处</th></tr></thead><tbody><tr><td>上下文工程 / 审查 AI 四关</td><td>14 章 §2/§4</td></tr><tr><td>token/温度/成本估算</td><td>15 章 §1</td></tr><tr><td>SSE 流式</td><td>15 章 §2</td></tr><tr><td>RAG 全链路 + 混合检索 + 评估</td><td>15 章 §5</td></tr><tr><td>tool_call 循环 / Agent 防死循环</td><td>16 章 §1/§2</td></tr><tr><td>MCP 是什么 + 与 function calling 关系</td><td>16 章 §4</td></tr><tr><td>prompt injection 缓解</td><td>16 章 §5</td></tr><tr><td>AI 交互状态机 / 人在环中</td><td>17 章 §1</td></tr><tr><td>端侧 vs 云端判据</td><td>17 章 §2</td></tr></tbody></table><h2 id="三、系统设计题-方法论见-13-章-§1-每题-15-分钟按五步走" tabindex="-1">三、系统设计题（方法论见 13 章 §1，每题 15 分钟按五步走） <a class="header-anchor" href="#三、系统设计题-方法论见-13-章-§1-每题-15-分钟按五步走" aria-label="Permalink to &quot;三、系统设计题（方法论见 13 章 §1，每题 15 分钟按五步走）&quot;">​</a></h2><ul><li>[ ] <strong>短网址系统</strong>（62 进制 + 唯一约束 + Redis 缓存）——答案思路见 13 章 §3.1</li><li>[ ] <strong>限流器</strong>（令牌桶 + 分布式 Redis）——13 章 §3.3</li><li>[ ] <strong>Feed 流</strong>（推拉结合 + 大 V 拉取）——13 章 §3.2</li><li>[ ] <strong>知识库全文搜索</strong>（MySQL FULLTEXT/ES + 缓存 + RAG 接入点）——13 章 §3.5</li><li>[ ] <strong>AI 问答产品</strong>（RAG + 缓存 + 成本 + 降级 + 流式）——<strong>全栈 + AI 王炸题</strong>，13 章 §3.4</li></ul><h2 id="四、项目深挖-star-抗追问-l3" tabindex="-1">四、项目深挖（STAR + 抗追问，L3） <a class="header-anchor" href="#四、项目深挖-star-抗追问-l3" aria-label="Permalink to &quot;四、项目深挖（STAR + 抗追问，L3）&quot;">​</a></h2><p>选 2-3 个你亲手做的项目（<strong>真实经历是最佳素材</strong>；若还没有成型项目，把 15/16 章的&quot;流式问答 + 检索 + 工具调用&quot;产品做完当作第一个）：</p><h3 id="star-模板-每个项目按这个写" tabindex="-1">STAR 模板（每个项目按这个写） <a class="header-anchor" href="#star-模板-每个项目按这个写" aria-label="Permalink to &quot;STAR 模板（每个项目按这个写）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S（背景）: 一句话&quot;为什么做、给谁、解决什么&quot;</span></span>
<span class="line"><span>T（任务）: 我的目标与约束（时间/资源/技术栈）</span></span>
<span class="line"><span>A（行动）: 技术选型 + 关键决策 + trade-off（为什么不用别的方案）</span></span>
<span class="line"><span>         + 踩坑 ≥2 个：怎么定位、怎么修</span></span>
<span class="line"><span>R（结果）: 量化（性能数字/用户量/成本下降/构建时间）</span></span>
<span class="line"><span>AI 实践 : 哪些环节用了 AI、怎么审查、审出过什么问题（差异化加分）</span></span></code></pre></div><h3 id="真实踩坑素材示范-以下为写法示范-替换成你自己的真实经历" tabindex="-1">真实踩坑素材示范（以下为写法示范，替换成你自己的真实经历） <a class="header-anchor" href="#真实踩坑素材示范-以下为写法示范-替换成你自己的真实经历" aria-label="Permalink to &quot;真实踩坑素材示范（以下为写法示范，替换成你自己的真实经历）&quot;">​</a></h3><ul><li><strong>&quot;首页预载 3.4MB TS 编译器&quot;</strong>：错误分包 → 定位（体积报告）→ 回滚默认分包 → 数据对比</li><li><strong>deploy swap 修斜杠</strong>：原子部署脚本 bug → 定位 → 修复</li><li><strong>Rolldown 下 vendor 分包回滚</strong>：构建器升级踩坑</li><li><strong>fetchUser TTL 缓存取舍</strong>：路由卡顿 → 加缓存 → 发现另有原因 → revert（诚实复盘）</li></ul><h3 id="高频追问自测-每题都能接" tabindex="-1">高频追问自测（每题都能接） <a class="header-anchor" href="#高频追问自测-每题都能接" aria-label="Permalink to &quot;高频追问自测（每题都能接）&quot;">​</a></h3><ul><li>[ ] &quot;如果数据量 ×100 会怎样&quot;（13 章扩展思维：缓存→读写分离→分片）</li><li>[ ] &quot;这个接口慢在哪，怎么证明&quot;（05 章排查流 + 11 章 EXPLAIN）</li><li>[ ] &quot;为什么选这个库/方案&quot;（说 trade-off，不说&quot;大家都用&quot;）</li><li>[ ] &quot;这个设计最坏情况会怎样&quot;（14 章四关的第四关）</li><li>[ ] &quot;你审出过 AI 的问题吗&quot;（14 章 §4：提前准备 2-3 个真实案例）</li></ul><h2 id="五、90-天行动清单-对齐-18-章" tabindex="-1">五、90 天行动清单（对齐 18 章） <a class="header-anchor" href="#五、90-天行动清单-对齐-18-章" aria-label="Permalink to &quot;五、90 天行动清单（对齐 18 章）&quot;">​</a></h2><h3 id="第-1-4-周-地基" tabindex="-1">第 1-4 周（地基） <a class="header-anchor" href="#第-1-4-周-地基" aria-label="Permalink to &quot;第 1-4 周（地基）&quot;">​</a></h3><ul><li>[ ] 01 JS、02 TS 到 L2（手写题开始滚动刷，每天 1-2 道进 Anki）</li><li>[ ] 03 框架、04 工程化到 L2，对照示例项目 web 代码逐模块过</li><li>[ ] 05 浏览器到 L2（URL 全链路练到 10 分钟）</li></ul><h3 id="第-5-8-周-后端" tabindex="-1">第 5-8 周（后端） <a class="header-anchor" href="#第-5-8-周-后端" aria-label="Permalink to &quot;第 5-8 周（后端）&quot;">​</a></h3><ul><li>[ ] 06 Node、07 HTTP、08 认证到 L2，对照示例项目 server 代码逐模块过</li><li>[ ] 09 API、10 后端工程化、11 数据库、12 缓存到 L2</li><li>[ ] 13 系统设计：五步法练熟 2 题（短网址 + 限流器）</li></ul><h3 id="第-9-12-周-ai-主线" tabindex="-1">第 9-12 周（AI 主线） <a class="header-anchor" href="#第-9-12-周-ai-主线" aria-label="Permalink to &quot;第 9-12 周（AI 主线）&quot;">​</a></h3><ul><li>[ ] 14 AI 协作贯穿：用 AI 在示例项目完成 2 个真实需求（plan→实现→测试→审查）</li><li>[ ] 15 到 L3：做出&quot;流式问答 + 文档检索&quot;产品（内存向量库起步 + eval 集）</li><li>[ ] 16 到 L3：给产品加工具调用 + Agent loop + 防死循环</li><li>[ ] 17 补体验：三态交互 + 降级 + 端云协同</li></ul><h3 id="第-13-16-周-收口" tabindex="-1">第 13-16 周（收口） <a class="header-anchor" href="#第-13-16-周-收口" aria-label="Permalink to &quot;第 13-16 周（收口）&quot;">​</a></h3><ul><li>[ ] 18 全面过一轮：手写题默写、八股口试（上表）、系统设计 5 题各走一遍</li><li>[ ] 把产品写成 STAR 项目，<strong>模拟面试自问自答 2 次（录音回听）</strong></li><li>[ ] 简历/作品集：放 1 个能在线演示的产品（把你自己的项目打磨成这个）</li></ul><h2 id="六、打卡总表-18-章" tabindex="-1">六、打卡总表（18 章） <a class="header-anchor" href="#六、打卡总表-18-章" aria-label="Permalink to &quot;六、打卡总表（18 章）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章</th><th>L2</th><th>L3</th><th>备注</th></tr></thead><tbody><tr><td>01 JavaScript 运行时深度</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>02 TypeScript 深度</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>03 前端框架原理</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>04 前端工程化</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>05 浏览器·网络·性能</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>06 Node.js 运行时</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>07 HTTP 框架与中间件</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>08 认证与授权</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>09 API 设计</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>10 后端工程化</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>11 数据库深度</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>12 缓存与分布式基础</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>13 系统设计实战</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>14 AI 协作工作流</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>15 LLM 与 RAG</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>16 Agent 与 MCP</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>17 AI 原生 UI 与端侧</td><td>⬜</td><td>⬜</td><td></td></tr><tr><td>18 面试备战</td><td>—</td><td>⬜</td><td></td></tr></tbody></table><h2 id="七、迁移网站备注" tabindex="-1">七、迁移网站备注 <a class="header-anchor" href="#七、迁移网站备注" aria-label="Permalink to &quot;七、迁移网站备注&quot;">​</a></h2><ul><li>本目录即&quot;课程内容&quot;：每章 = 课程条目，README 能力图谱 = 首页地图，「达标标准」= 进度系统</li><li>手写题可做成&quot;在线做题 + 判题&quot;；系统设计题可做成&quot;看答案前先自己写&quot;</li><li>保持纯 Markdown，迁移前不绑框架（详见 README 维护约定）</li></ul>`,40)])])}const q=d(l,[["render",o]]);export{b as __pageData,q as default};
